export type AttachmentText = {
  id: string;
  filename: string;
  content_type: string;
  /**
   * Bytes, as stored.
   */
  size: number;
  /**
   * How it was read. `pdf`: the text layer, a form feed between pages. `docx`: headers, body and footers, table rows tab-separated; footnotes and comments left out. `xlsx`: each sheet as `## Sheet: <name>` and CSV, dates as Excel serial numbers.
   */
  format: 'text' | 'pdf' | 'docx' | 'xlsx';
  /**
   * The file as text. With `body=clean`, hidden characters removed and lines posing as a chat turn marked, under a first line saying what changed; for a document, also what it hid from a person opening it (a hidden Word run, a hidden sheet, row or column).
   */
  text: string;
  /**
   * True when the file ran past 200,000 characters and the rest was cut.
   */
  truncated: boolean;
  /**
   * Whether the text tries to steer the agent reading it, judged with the sender of the message it came with. Null on mail this account sent.
   */
  firewall: {
    /**
     * `suspicious` when any signal fired. At an address that holds suspicious mail (`hold_suspicious`) the message is also held for a person: `is_held`.
     */
    verdict: 'clean' | 'suspicious';
    /**
     * The rules that fired, most specific first. Empty when the verdict is `clean`.
     */
    signals: Array<{
      kind:
        | 'hidden_text'
        | 'invisible_characters'
        | 'assistant_directive'
        | 'role_spoof'
        | 'quoted_directive'
        | 'lookalike_sender'
        | 'display_name_spoof'
        | 'unauthenticated_with_directive'
        | 'exfiltration_request';
      /**
       * What was found, with a short quote of it.
       */
      detail: string;
      where: 'subject' | 'text' | 'html' | 'from' | 'quoted';
    }>;
    /**
     * Bumped when the rules change in a way that could change a verdict.
     */
    version: number;
  } | null;
};

